def _rel(typ, fact, rel):
    """Достоверность 1-5 по типу источника: официальные цены и безопасность выше, заявления главной и отзывы с малой выборкой ниже."""
    f = fact.lower()
    if typ == "отзывы":
        m = re.search(r"(\d+) отзыв", f)
        n = int(m.group(1)) if m else 0
        if "нет" in f or "0 отзывов" in f or n < 10:
            return 3
        return 4 if n < 100 else 5
    if typ == "тарифы":
        return 4 if "без сумм" in f else 5
    if typ == "главная":
        return 5 if "soc 2" in f else 4
    if typ == "цены":
        return 5
    if typ == "безопасность":
        return 5 if "soc 2" in f else 4
    if typ in ("правовые", "интеграции"):
        return 4
    if typ == "пробный доступ":
        return 5
    return min(rel, 4)


PAGES = [(a, b, c, d, e, f, _rel(d, f, g), h) for (a, b, c, d, e, f, g, h) in PAGES]

